                module Action
                module SelectClass8ForRecord
                ; Документация [алгоритм и проверка](../../Docs/ActionSelectClass8.md)
                ; -----------------------------------------
                ; Поиск первой записи класса 8 и сохранение её индекса в текущей записи
                ; исходная запись 17, адреса E97C..E98C
                ; In:
                ;   HL, DE, BC и AF числовых аргументов не задают
                ;   IX указывает текущую FActionRecord с доступным ProximityIndex, IY исходного указателя не задаёт
                ;   действуют договоры FindRecordByCode и RecordIYToIndex, от A100 достижима цель либо маркер
                ;   читается Component0.High, для активной записи доступны остальные фазовые поля, класс, состояние и порог
                ;   OffsetScaleLow и OffsetScaleHigh активной записи доступны для записи, ACTION банка 0 и общая RAM доступны
                ;   действует договор ApplyObjectOffsetVector, шесть байтов под SP и внешний возврат не перекрывают его код, таблицы, операнды и результаты
                ;   IRQ и повторный вход исключены
                ;   шесть временных байтов CPU-стека и результаты вычислителя не перекрывают поисковый список и текущую запись
                ; Out:
                ;   поиск выполняется до общего хвоста, IY на его границе указывает первую активную запись полного класса 08 либо достигнутый маркер
                ;   ProximityIndex получает найденный индекс только при успехе поиска, при отсутствии цели сохраняется, ProximityClass сохраняется в обоих случаях
                ;   при Component0.High текущей IX-записи=80 полный выход сохраняет HL и входной E, возвращает D=08, BC=0040, AF=8042
                ;   на этом маркерном пути HL', DE', BC', AF', IX и найденный IY сохраняются, собственная запись ProximityIndex не откатывается
                ;   на маркерном пути SP=входной SP+2, R получает полные M1 FindRecordByCode плюс 7 при отсутствии цели либо плюс 27 при успехе
                ;   на активной ветви нижеследующие результаты вычислителя относятся к V из прежнего OffsetScaleLow и выбранного старшего байта
                ;   HL=(-Q) AND FFFF при бите 7 S=1, иначе HL=Q, DE=Q при бите 7 S=1, иначе DE=abs(V)
                ;   BC - B=W[Offset0], C=0
                ;   AF - A=S, F от 16-разрядного 0-Q при бите 7 S=1, иначе флаги логического XOR с результатом S
                ;   HL', DE', BC' сохраняются
                ;   AF' - A'=U, F'=(U AND 28) OR (40 при U=0) OR (10 при 2*((P SHR 16) AND 0F)+(U AND 1)>0F), остальные биты F' нулевые
                ;   IX восстановлен, IYH сохраняется, IYL=W[(Offset1+64) AND FF]
                ;   Coefficient0..2 содержат результат построителя, Base0..2 содержат три произведения с одним входным V
                ;   SP=входной SP+2, I, IM, IFF и paging сохраняются, порты не используются
                ;   Offset0..2 получают OffsetPhase0, wrap8(OffsetPhase1+80) и OffsetPhase2
                ;   OffsetScaleLow получает wrap8(старое+1), если этот кандидат ниже Phase2OrTarget, иначе сохраняется прежний байт
                ;   OffsetScaleHigh обнулён при ClassCode<10 и StateCode не равном 13, иначе сохранён
                ;   на активной ветви общий хвост добавляет к R 30+Hold+4*Small+2*Small*Different M1 подготовки плюс полный вычислитель, старший бит R сохраняется
                ;   на активном пути сохранённый IYH равен HIGH адреса, найденного поиском, IYL заменяется результатом общего вычислителя
                ;   собственный поиск и преобразование добавляют полные M1 FindRecordByCode плюс 3 при отсутствии цели либо плюс 23 при успехе, затем исполняется общий хвост
                ;   на всех путях внешний RET снимает исходное слово возврата, I, IM, IFF и paging сохраняются, OUT отсутствует
                ; Corrupt:
                ;   HL, DE, BC, AF, AF', IYL, R, Coefficient0..2, Base0..2 и шесть временных байтов CPU-стека, три фазовых операнда и условно OffsetScaleLow/OffsetScaleHigh, IYH после выбора адреса и ProximityIndex при успехе поиска
                ;   на маркерном пути изменены только D, BC, AF, IY, R, условно ProximityIndex и остаточные слова до шести байтов CPU-стека
                ; Note:
                ;   класс сравнивается целиком с 08, остальные коды 00..FF не приравниваются ему по маске
                ;   перед F0F8 Z установлен при обоих результатах поиска, но это промежуточные флаги, окончательный AF задаёт общий хвост
                ;   физические исходные слоты дают индексы 0..24, глобальный лимит произвольного игрового списка этим не устанавливается
                ;   6656 сценариев проверили все 256 кодов проверяемой записи и 26 вариантов позиции, точные регистры, флаги, R и все записи
                ;   прежняя проверка 6656 случаев заканчивается перед F0F8, новая композиция 13312 случаев исполняет поиск, преобразование, общий хвост и три умножения до внешнего RET
                ;   в новой композиции IX вне поискового списка, проверены активная и маркерная текущие записи, оба исхода поиска, регистры с R, восемь банков и кратность записей
                ;   самовыбор IX=IY проверен прежней моделью только до F0F8, полное произведение списков и фазовых полей не перебрано
                ;   успешный индекс и его флаги существуют на границе F0F8, окончательные A и IYL не возвращают результат поиска на активной ветви
                ;   эффективное слово V перед 6D06 содержит прежний OffsetScaleLow в E и итоговый OffsetScaleHigh в D, это не входное DE всей процедуры
                ;   Hold=1 при сохранении прежнего младшего масштаба, иначе 0, Small=1 при ClassCode<10, Different=1 при StateCode не равном 13, иначе соответствующий признак нулевой
                ;   10, 13 и 80 в условиях полей обозначают шестнадцатеричные коды, числа M1 десятичные
                ;   все возможные списки, аппаратные IRQ, точные T, сборка и нативный запуск не проверялись
                ;   c2 обозначает третий байтовый коэффициент, m=abs(s8(c2)) AND 7F, P=m*abs(V), Q=floor(P/128), U=P SHR 15, S=c2 XOR HIGH слова V
                ;   нулевой фактор для коэффициента 80 сохранён, знак определяется исходным байтом коэффициента и старшим байтом V
                ;   каждое Base равно -floor((abs(s8(c_i)) AND 7F)*abs(V)/128) при бите 7 c_i XOR HIGH V, иначе положительному частному, всё по модулю 65536
                ;   шесть временных байтов после возврата содержат исходный IX по SP-2, слово V по SP-4 и внутренний возврат 6D0C по SP-6, POP не очищает RAM
                ;   для фактора m>0 умножение даёт 35+floor(log2(m))+2*popcount(m) M1, при m=0 даёт 32 M1
                ;   к каждому умножению добавляются семь M1 при V<0, две при бите 7 коэффициента и четыре при бите 7 его XOR HIGH V
                ; -----------------------------------------
                ; Поиск первой активной записи с полным кодом класса 08.
Entry:          LD D, @ActionSelectClass8Const.ClassCode
                CALL @Action.FindRecordByCode.Entry
                JP Z, @Action.PrepareObjectOffsetTransform.Entry                ; переход, если поиск достиг маркера без класса 8, сохранить прежний индекс и продолжить общий хвост

                ; Преобразование адреса найденной записи IY в её байтовый индекс без чтения координат.
                CALL @Action.RecordIYToIndex.Entry
                ; Сохранение найденного индекса в поле ProximityIndex текущей записи IX.
                LD (IX + @FActionRecord.ProximityIndex), A
                ; Передача общего внешнего CPU-стека подготовителю смещений текущей записи.
                JP @Action.PrepareObjectOffsetTransform.Entry

                endmodule
                endmodule
